INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1700, 'recruit', '/rɪˈkruːt/', 'verb', '{"zh-TW":["招募；招聘"],"en":["to find new people to join"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cruit","meaning":"grow (生長)"}}', 'recruit new employees / recruit talent / recruitment drive', '[{"en":"We are recruiting for several positions.","zh-TW":"我們正在招聘幾個職位。"},{"en":"The company recruited 50 new graduates.","zh-TW":"公司招募了50名應屆畢業生。"}]', '{"noun":"recruitment, recruiter, recruit"}', NULL, 3, 1700),
(1701, 'reduce', '/rɪˈdjuːs/', 'verb', '{"zh-TW":["減少；降低"],"en":["to make smaller in size or amount"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"duce","meaning":"lead (引導)"}}', 'reduce costs / reduce emissions / reduce the risk', '[{"en":"We need to reduce operating costs.","zh-TW":"我們需要降低營運成本。"},{"en":"The new policy aims to reduce emissions.","zh-TW":"新政策旨在減少排放。"}]', '{"noun":"reduction"}', NULL, 2, 1701),
(1702, 'refer', '/rɪˈfɜːr/', 'verb', '{"zh-TW":["提到；參考","轉介"],"en":["to mention","to direct someone"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry (攜帶)"}}', 'refer to / refer sb. to / with reference to', '[{"en":"Please refer to the user manual.","zh-TW":"請參考用戶手冊。"},{"en":"I was referred to the HR department.","zh-TW":"我被轉介到人資部門。"}]', '{"noun":"reference, referral, referee"}', NULL, 2, 1702),
(1703, 'referee', '/ˌrɛfəˈriː/', 'noun', '{"zh-TW":["裁判"],"en":["a person who makes sure rules are followed in a game"]}', NULL, 'referee a match / referee''s decision', '[{"en":"The referee blew the whistle.","zh-TW":"裁判吹響了哨子。"},{"en":"The referee''s decision is final.","zh-TW":"裁判的決定是最終的。"}]', NULL, NULL, 3, 1703),
(1704, 'reference', '/ˈrɛfərəns/', 'noun', '{"zh-TW":["參考；參照","推薦信"],"en":["a source of information","a letter of recommendation"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry"},"suffix":{"text":"-ence","meaning":"名詞後綴"}}', 'for reference / reference number / provide references', '[{"en":"Please keep this for future reference.","zh-TW":"請保留此文件以供未來參考。"},{"en":"Can you provide two professional references?","zh-TW":"你能提供兩份專業推薦嗎？"}]', '{"verb":"refer"}', NULL, 3, 1704),
(1705, 'reflect', '/rɪˈflɛkt/', 'verb', '{"zh-TW":["反映；反射","反思"],"en":["to show or express","to think carefully"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"flect","meaning":"bend (彎曲)"}}', 'reflect on / reflect changes / reflect the views', '[{"en":"The report reflects the current market conditions.","zh-TW":"報告反映了當前市場狀況。"},{"en":"Take time to reflect on your progress.","zh-TW":"花時間反思你的進展。"}]', '{"noun":"reflection","adjective":"reflective"}', NULL, 3, 1705),
(1706, 'reform', '/rɪˈfɔːrm/', 'noun', '{"zh-TW":["改革"],"en":["a change made to improve a system","a change made to improve something"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"form","meaning":"form/shape (形成)"},"logic":"重新形成，即「改革」。"}', 'education reform / tax reform / reform the system; economic reform / reform the system / tax reform', '[{"en":"The government introduced economic reforms.","zh-TW":"政府推行了經濟改革。"},{"en":"Healthcare reform is urgently needed.","zh-TW":"醫療改革迫在眉睫。"},{"en":"The government announced major tax reforms.","zh-TW":"政府宣布了重大稅制改革。"},{"en":"Healthcare reform is a priority.","zh-TW":"醫療改革是優先事項。"}]', '{"verb":"reform","noun2":"reformer","noun":"reformer"}', NULL, 2, 1706),
(1707, 'refund', '/ˈriːfʌnd/', 'noun', '{"zh-TW":["退款"],"en":["money returned to a buyer"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"fund","meaning":"pour/money (注入/資金)"},"logic":"把錢倒回去，即「退款」。"}', 'full refund / request a refund; full refund / request a refund / refund policy', '[{"en":"I would like to request a refund.","zh-TW":"我想要求退款。"},{"en":"They issued a full refund within 24 hours.","zh-TW":"他們在24小時內全額退款。"},{"en":"We will issue a full refund.","zh-TW":"我們將全額退款。"},{"en":"Please check our refund policy.","zh-TW":"請查看我們的退款政策。"}]', '{"verb":"refund","adjective":"refundable"}', NULL, 2, 1707),
(1708, 'regard', '/rɪˈɡɑːrd/', 'verb', '{"zh-TW":["認為；看待"],"en":["to consider; to think of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch (看)"}}', 'regard as / with regard to / in this regard / regardless', '[{"en":"She is widely regarded as an expert.","zh-TW":"她被廣泛認為是專家。"},{"en":"With regard to your inquiry, please see below.","zh-TW":"關於您的詢問，請見下方。"}]', '{"noun":"regard, regards","preposition":"regarding"}', NULL, 2, 1708),
(1709, 'regardless', '/rɪˈɡɑːrdləs/', 'adverb', '{"zh-TW":["不管；無論如何"],"en":["without being affected by"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch"},"suffix":{"text":"-less","meaning":"without (無)"}}', 'regardless of / regardless of the cost', '[{"en":"We will proceed regardless of the obstacles.","zh-TW":"無論有什麼障礙我們都將繼續。"},{"en":"The rule applies regardless of seniority.","zh-TW":"規則不論資歷均適用。"}]', NULL, NULL, 4, 1709),
(1710, 'region', '/ˈriːdʒən/', 'noun', '{"zh-TW":["地區；區域"],"en":["a particular area or part"]}', NULL, 'in the region / regional office / Asia-Pacific region', '[{"en":"The company has offices in every region.","zh-TW":"公司在每個地區都有辦公室。"},{"en":"Economic growth varies by region.","zh-TW":"經濟增長因地區而異。"}]', '{"adjective":"regional","adverb":"regionally"}', NULL, 2, 1710),
(1711, 'register', '/ˈredʒɪstər/', 'noun', '{"zh-TW":["收銀機；登記","登記；註冊"],"en":["a cash register","to officially record information","to officially record or enroll"]}', '{"root":{"text":"gest","meaning":"carry (攜帶)"},"prefix":{"text":"re-","meaning":"back (回)"},"logic":"帶回紀錄，指登記或收銀機。"}', 'cash register / register for a course; register for / register a complaint / registered office', '[{"en":"The cashier opened the register to make change.","zh-TW":"收銀員打開收銀機找零。"},{"en":"Please register at the front desk.","zh-TW":"請在前台登記。"},{"en":"You must register before attending the event.","zh-TW":"參加活動前必須註冊。"},{"en":"The company is registered in Delaware.","zh-TW":"公司在德拉瓦州註冊。"}]', '{"noun":"registration","adjective":"registered"}', NULL, 3, 1711),
(1712, 'regulate', '/ˈrɛɡjuleɪt/', 'verb', '{"zh-TW":["規範；調節","監管；調節"],"en":["to control something by rules","to control or supervise by rules","to control by rules"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其按規則運行，即「規範」。"}', 'regulate industry / government regulated; regulate the industry / regulate temperature; regulate the industry / strictly regulated', '[{"en":"The government regulates the banking industry.","zh-TW":"政府規範銀行業。"},{"en":"This law regulates food safety.","zh-TW":"這項法律規範食品安全。"},{"en":"This thermostat regulates room temperature.","zh-TW":"這個恆溫器調節室溫。"},{"en":"The government regulates the financial sector.","zh-TW":"政府監管金融業。"},{"en":"Prices are regulated by market forces.","zh-TW":"價格由市場力量調節。"}]', '{"noun":"regulation","noun2":"regulator","adjective":"regulatory"}', NULL, 3, 1712),
(1713, 'regulation', '/ˌrɛɡjuˈleɪʃən/', 'noun', '{"zh-TW":["法規；規定"],"en":["an official rule or law"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'comply with regulations / safety regulations / government regulation', '[{"en":"All companies must comply with safety regulations.","zh-TW":"所有公司必須遵守安全法規。"},{"en":"New regulations take effect next month.","zh-TW":"新法規下月生效。"}]', '{"verb":"regulate","adjective":"regulatory","noun":"regulator"}', NULL, 4, 1713),
(1714, 'rehearsal', '/rɪˈhɜːrsəl/', 'noun', '{"zh-TW":["排練；彩排"],"en":["a practice session before a performance"]}', NULL, 'dress rehearsal / rehearsal room', '[{"en":"We have rehearsal every evening this week.","zh-TW":"這週我們每晚都有排練。"},{"en":"The dress rehearsal is tomorrow.","zh-TW":"彩排在明天。"}]', '{"verb":"rehearse"}', NULL, 3, 1714),
(1715, 'reimburse', '/ˌriːɪmˈbɜːrs/', 'verb', '{"zh-TW":["報銷；償還"],"en":["to pay back money spent"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"im-burse","meaning":"purse (錢包)"}}', 'reimburse expenses / reimburse sb. for / reimbursement policy', '[{"en":"The company will reimburse travel expenses.","zh-TW":"公司將報銷差旅費。"},{"en":"You will be reimbursed within 30 days.","zh-TW":"你將在30天內獲得報銷。"}]', '{"noun":"reimbursement"}', NULL, 3, 1715),
(1716, 'reinforce', '/ˌriːɪnˈfɔːrs/', 'verb', '{"zh-TW":["加強；鞏固"],"en":["to make stronger"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"in-force","meaning":"strengthen (加強)"}}', 'reinforce the message / reinforce a policy', '[{"en":"This reinforces our commitment to quality.","zh-TW":"這強化了我們對品質的承諾。"},{"en":"Training reinforces best practices.","zh-TW":"培訓鞏固了最佳做法。"}]', '{"noun":"reinforcement"}', NULL, 3, 1716),
(1717, 'reject', '/rɪˈdʒekt/', 'verb', '{"zh-TW":["拒絕；駁回"],"en":["to refuse to accept or consider","to refuse to accept"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ject","meaning":"throw (丟)"},"logic":"丟回去，即「拒絕」。"}', 'reject an offer / reject a proposal; reject a proposal / reject an application / flat out reject', '[{"en":"The committee rejected his proposal.","zh-TW":"委員會駁回了他的提案。"},{"en":"She rejected the job offer.","zh-TW":"她拒絕了這份工作邀約。"},{"en":"The board rejected the merger proposal.","zh-TW":"董事會駁回了合併提案。"},{"en":"Her application was rejected.","zh-TW":"她的申請被拒絕了。"}]', '{"noun":"rejection"}', NULL, 2, 1717),
(1718, 'relate', '/rɪˈleɪt/', 'verb', '{"zh-TW":["與...有關","敘述"],"en":["to connect or be relevant","to tell"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"late","meaning":"carry (攜帶)"}}', 'relate to / related to / in relation to', '[{"en":"This issue relates to our earlier discussion.","zh-TW":"這問題與我們之前的討論有關。"},{"en":"The increase is related to market demand.","zh-TW":"增長與市場需求有關。"}]', '{"noun":"relation, relationship","adjective":"related, relative","adverb":"relatively"}', NULL, 2, 1718),
(1719, 'release', '/rɪˈliːs/', 'verb', '{"zh-TW":["發布；釋放"],"en":["to make available; to set free"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"lease","meaning":"let go (放開)"}}', 'release a product / press release / release information', '[{"en":"The company will release the new product in March.","zh-TW":"公司將於三月發布新產品。"},{"en":"A press release was issued today.","zh-TW":"今天發布了新聞稿。"}]', '{"noun":"release"}', NULL, 3, 1719),
(1720, 'relevant', '/ˈreləvənt/', 'adjective', '{"zh-TW":["相關的；切題的"],"en":["closely connected to the matter at hand","closely connected to the matter"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"lev","meaning":"raise (提起)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"能再次被提起的重要資訊，即「相關的」。"}', 'relevant experience / relevant information / highly relevant; relevant experience / relevant to / relevant information', '[{"en":"Please include all relevant information.","zh-TW":"請包含所有相關資訊。"},{"en":"Her experience is highly relevant to this position.","zh-TW":"她的經驗與這個職位高度相關。"},{"en":"Please include all relevant experience on your resume.","zh-TW":"請在履歷中包含所有相關經驗。"},{"en":"This is not relevant to the discussion.","zh-TW":"這與討論無關。"}]', '{"noun":"relevance","adverb":"relevantly"}', NULL, 3, 1720),
(1721, 'reliable', '/rɪˈlaɪəbl/', 'adjective', '{"zh-TW":["可靠的；可信賴的"],"en":["able to be trusted"]}', '{"root":{"text":"rely","meaning":"depend (依賴)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'reliable source / reliable service / highly reliable', '[{"en":"We need a reliable supplier.","zh-TW":"我們需要可靠的供應商。"},{"en":"The system has proven to be highly reliable.","zh-TW":"系統已被證明非常可靠。"}]', '{"noun":"reliability","adverb":"reliably","verb":"rely"}', NULL, 3, 1721),
(1722, 'relief', '/rɪˈliːf/', 'noun', '{"zh-TW":["緩解；減輕","救濟"],"en":["the feeling of comfort after anxiety","aid given"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"lief","meaning":"lift (舉起)"}}', 'tax relief / disaster relief / to one''s relief / provide relief', '[{"en":"The tax relief benefits small businesses.","zh-TW":"稅收減免有利於小企業。"},{"en":"To our relief, the problem was resolved quickly.","zh-TW":"令我們欣慰的是，問題很快解決了。"}]', '{"verb":"relieve"}', NULL, 2, 1722),
(1723, 'reluctant', '/rɪˈlʌktənt/', 'adjective', '{"zh-TW":["不情願的","不情願的；勉強的"],"en":["unwilling and hesitant","unwilling to do something"]}', '{"prefix":{"text":"re-","meaning":"against (反對)"},"root":{"text":"luct","meaning":"struggle (掙扎)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對某事掙扎抗拒的，即「不情願的」。"}', 'reluctant to / a reluctant participant; reluctant to do / be reluctant', '[{"en":"He was reluctant to admit his mistake.","zh-TW":"他不情願承認自己的錯誤。"},{"en":"She was a reluctant participant in the debate.","zh-TW":"她是辯論中不情願的參與者。"},{"en":"He was reluctant to accept the transfer.","zh-TW":"他不情願接受調動。"},{"en":"Many employees are reluctant to change.","zh-TW":"許多員工不願意改變。"}]', '{"noun":"reluctance","adverb":"reluctantly"}', NULL, 3, 1723),
(1724, 'rely', '/rɪˈlaɪ/', 'verb', '{"zh-TW":["依賴；信賴","依賴；依靠"],"en":["to depend on with full trust","to depend on with confidence"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ly","meaning":"bind (綁)"},"logic":"被綁回到某人身上（依靠），即「依賴」。"}', 'rely on / rely heavily on; rely on / rely heavily on / reliable', '[{"en":"We rely on technology for communication.","zh-TW":"我們依賴科技來溝通。"},{"en":"You can rely on her to do a good job.","zh-TW":"你可以信賴她會做好。"},{"en":"We rely heavily on technology.","zh-TW":"我們嚴重依賴技術。"},{"en":"You can rely on our team to deliver.","zh-TW":"你可以依靠我們團隊交付。"}]', '{"adjective":"reliable","noun":"reliance","noun2":"reliability"}', NULL, 1, 1724),
(1725, 'remain', '/rɪˈmeɪn/', 'verb', '{"zh-TW":["保持；仍然是","剩餘"],"en":["to continue in the same state","to be left"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"main","meaning":"stay (停留)"}}', 'remain unchanged / remain competitive / remaining balance', '[{"en":"Prices remain stable this quarter.","zh-TW":"本季度價格保持穩定。"},{"en":"Several issues remain unresolved.","zh-TW":"幾個問題仍未解決。"}]', '{"noun":"remainder, remains","adjective":"remaining"}', NULL, 2, 1725),
(1726, 'remarkable', '/rɪˈmɑːrkəbl/', 'adjective', '{"zh-TW":["卓越的；非凡的"],"en":["worthy of attention; extraordinary"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mark","meaning":"notice (注意)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'remarkable achievement / remarkable growth', '[{"en":"The company has shown remarkable growth.","zh-TW":"公司展現了非凡的增長。"},{"en":"Her performance was truly remarkable.","zh-TW":"她的表現真正非凡。"}]', '{"adverb":"remarkably"}', NULL, 4, 1726),
(1727, 'remedy', '/ˈrɛmɪdi/', 'noun', '{"zh-TW":["補救措施；療法"],"en":["a solution to a problem"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"med","meaning":"heal (治療)"}}', 'find a remedy / legal remedy / remedy the situation', '[{"en":"We must find a remedy for this issue.","zh-TW":"我們必須找到解決方案。"},{"en":"Legal remedies are available.","zh-TW":"可採取法律補救措施。"}]', '{"verb":"remedy","adjective":"remedial"}', NULL, 2, 1727),
(1728, 'remember', '/rɪˈmɛmbər/', 'verb', '{"zh-TW":["記得；想起"],"en":["to have in mind","to recall"]}', NULL, 'remember to / if I remember correctly', '[{"en":"Remember to submit the report.","zh-TW":"記得提交報告。"},{"en":"If I remember correctly, the deadline is Friday.","zh-TW":"如果我沒記錯，截止日期是週五。"}]', '{"verb":"remember","noun":"remembrance"}', NULL, 3, 1728),
(1729, 'remind', '/rɪˈmaɪnd/', 'verb', '{"zh-TW":["提醒"],"en":["to cause someone to remember"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mind","meaning":"mind (心智)"}}', 'remind sb. of / remind sb. to do / a reminder', '[{"en":"Please remind me to call the client.","zh-TW":"請提醒我打給客戶。"},{"en":"This is a reminder that reports are due Friday.","zh-TW":"這是提醒：報告週五到期。"}]', '{"noun":"reminder"}', NULL, 2, 1729),
(1730, 'remote', '/rɪˈmoʊt/', 'adjective', '{"zh-TW":["遠程的；偏遠的"],"en":["far away; operating from a distance"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"mote","meaning":"move (移動)"}}', 'remote work / remote access / remote location', '[{"en":"Most employees now work remotely.","zh-TW":"大多數員工現在遠程工作。"},{"en":"Remote access to the system is available.","zh-TW":"系統可以遠程訪問。"}]', '{"adverb":"remotely","noun":"remoteness"}', NULL, 2, 1730),
(1731, 'remove', '/rɪˈmuːv/', 'verb', '{"zh-TW":["移除；消除"],"en":["to take away"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"move","meaning":"move (移動)"}}', 'remove from / remove obstacles / remove barriers', '[{"en":"Please remove your belongings from the desk.","zh-TW":"請把你的物品從桌上移走。"},{"en":"We need to remove barriers to entry.","zh-TW":"我們需要消除進入障礙。"}]', '{"noun":"removal","adjective":"removable"}', NULL, 2, 1731),
(1732, 'renew', '/rɪˈnjuː/', 'verb', '{"zh-TW":["更新；續約"],"en":["to make valid for another period"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"new","meaning":"new (新)"}}', 'renew a contract / renew a subscription / renewal date', '[{"en":"Don''t forget to renew your license.","zh-TW":"別忘了更新你的執照。"},{"en":"The contract was renewed for another year.","zh-TW":"合約續約了一年。"}]', '{"noun":"renewal","adjective":"renewable"}', NULL, 2, 1732),
(1733, 'renovate', '/ˈrɛnəveɪt/', 'verb', '{"zh-TW":["翻新；修繕","翻修"],"en":["to repair and improve a building","to restore to good condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'renovate the office / recently renovated; renovate the building / newly renovated', '[{"en":"The office was recently renovated.","zh-TW":"辦公室最近進行了翻新。"},{"en":"They plan to renovate the building.","zh-TW":"他們計劃翻新大樓。"},{"en":"The hotel was recently renovated.","zh-TW":"酒店最近翻新了。"},{"en":"Plans to renovate the office were approved.","zh-TW":"翻新辦公室的計劃已獲批。"}]', '{"noun":"renovation"}', NULL, 3, 1733),
(1734, 'rent', '/rɛnt/', 'noun', '{"zh-TW":["租金"],"en":["payment for use of property"]}', NULL, 'pay rent / rent out / for rent / rental agreement', '[{"en":"Office rent has increased significantly.","zh-TW":"辦公室租金大幅上漲。"},{"en":"The apartment is available for rent.","zh-TW":"公寓可供出租。"}]', '{"verb":"rent","noun":"rental, renter"}', NULL, 1, 1734),
(1735, 'repair', '/rɪˈpɛr/', 'verb', '{"zh-TW":["修理；修復"],"en":["to fix something broken"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"pair","meaning":"prepare (準備)"}}', 'repair damage / under repair / repair costs', '[{"en":"The equipment is being repaired.","zh-TW":"設備正在維修中。"},{"en":"Repair costs exceeded our estimates.","zh-TW":"修理費用超出了我們的估計。"}]', '{"noun":"repair, reparation"}', NULL, 2, 1735),
(1736, 'replace', '/rɪˈpleɪs/', 'verb', '{"zh-TW":["取代；更換"],"en":["to put something new in place of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"place","meaning":"place (放置)"}}', 'replace with / replace sb. / find a replacement', '[{"en":"We will replace the old system with a new one.","zh-TW":"我們將用新系統取代舊系統。"},{"en":"She was hired to replace the former manager.","zh-TW":"她被聘來接替前任經理。"}]', '{"noun":"replacement","adjective":"replaceable"}', NULL, 3, 1736),
(1737, 'represent', '/ˌrɛprɪˈzɛnt/', 'verb', '{"zh-TW":["代表；象徵"],"en":["to act or speak for someone; to symbolize"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"present","meaning":"present (呈現)"}}', 'represent the company / represent a change', '[{"en":"She represents the company at trade shows.","zh-TW":"她代表公司參加商展。"},{"en":"This represents a significant change in policy.","zh-TW":"這代表政策的重大改變。"}]', '{"noun":"representation, representative","adjective":"representative"}', NULL, 3, 1737),
(1738, 'reputation', '/ˌrɛpjuˈteɪʃən/', 'noun', '{"zh-TW":["聲譽；名譽"],"en":["the opinion people have about someone"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"put","meaning":"think (思考)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'good reputation / damage one''s reputation / build a reputation', '[{"en":"The company has an excellent reputation.","zh-TW":"公司享有卓越聲譽。"},{"en":"One mistake can damage your reputation.","zh-TW":"一個錯誤可以損害你的聲譽。"}]', '{"adjective":"reputable"}', NULL, 4, 1738),
(1739, 'request', '/rɪˈkwɛst/', 'noun', '{"zh-TW":["請求；要求"],"en":["an act of asking for something"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quest","meaning":"seek (尋求)"}}', 'make a request / upon request / request for information', '[{"en":"We received a request for additional funding.","zh-TW":"我們收到了追加資金的請求。"},{"en":"Samples are available upon request.","zh-TW":"樣品可依要求提供。"}]', '{"verb":"request"}', NULL, 3, 1739),
(1740, 'require', '/rɪˈkwaɪər/', 'verb', '{"zh-TW":["需要；要求"],"en":["to need; to demand by rule"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quire","meaning":"seek (尋求)"}}', 'require approval / required by law / as required', '[{"en":"This position requires five years of experience.","zh-TW":"此職位需要五年經驗。"},{"en":"All visitors are required to sign in.","zh-TW":"所有訪客必須登記。"}]', '{"noun":"requirement","adjective":"required"}', NULL, 3, 1740),
(1741, 'research', '/rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["研究；調查"],"en":["careful study of a subject"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"search","meaning":"search (搜索)"}}', 'conduct research / research and development / market research', '[{"en":"The company invests heavily in R&D.","zh-TW":"公司大量投資研發。"},{"en":"Further research is needed.","zh-TW":"需要進一步研究。"}]', '{"verb":"research","noun":"researcher"}', NULL, 3, 1741),
(1742, 'reservation', '/ˌrɛzərˈveɪʃən/', 'noun', '{"zh-TW":["預訂","保留意見"],"en":["a booking","doubt or uncertainty"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'make a reservation / have reservations about / without reservation', '[{"en":"I''d like to make a reservation for two.","zh-TW":"我想預訂兩人座。"},{"en":"I have some reservations about the plan.","zh-TW":"我對計劃有些保留意見。"}]', '{"verb":"reserve"}', NULL, 4, 1742),
(1743, 'reserve', '/rɪˈzɜːrv/', 'verb', '{"zh-TW":["預訂；保留"],"en":["to book; to keep for later use"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serve","meaning":"keep (保持)"}}', 'reserve a room / cash reserves / reserve the right', '[{"en":"Please reserve a conference room.","zh-TW":"請預訂一間會議室。"},{"en":"We reserve the right to cancel.","zh-TW":"我們保留取消的權利。"}]', '{"noun":"reserve, reservation","adjective":"reserved"}', NULL, 3, 1743),
(1744, 'reside', '/rɪˈzaɪd/', 'verb', '{"zh-TW":["居住"],"en":["to live in a place"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"side","meaning":"sit (坐)"}}', 'reside in / place of residence', '[{"en":"She resides in Tokyo.","zh-TW":"她居住在東京。"},{"en":"Please provide your place of residence.","zh-TW":"請提供您的居住地。"}]', '{"noun":"residence, resident, residency","adjective":"residential"}', NULL, 2, 1744),
(1745, 'resign', '/rɪˈzaɪn/', 'verb', '{"zh-TW":["辭職"],"en":["to voluntarily leave a job"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sign","meaning":"sign (簽署)"}}', 'resign from / letter of resignation / resign as', '[{"en":"He resigned from his position as CEO.","zh-TW":"他辭去了執行長一職。"},{"en":"Please submit your resignation in writing.","zh-TW":"請以書面形式提交辭呈。"}]', '{"noun":"resignation"}', NULL, 2, 1745),
(1746, 'resist', '/rɪˈzɪst/', 'verb', '{"zh-TW":["抵抗；抵制"],"en":["to oppose or fight against"]}', '{"prefix":{"text":"re-","meaning":"against"},"root":{"text":"sist","meaning":"stand (站立)"}}', 'resist change / resist pressure / hard to resist', '[{"en":"Many employees resist organizational change.","zh-TW":"許多員工抵制組織變革。"},{"en":"The offer was hard to resist.","zh-TW":"這個提議很難拒絕。"}]', '{"noun":"resistance","adjective":"resistant"}', NULL, 2, 1746),
(1747, 'resolve', '/rɪˈzɒlv/', 'verb', '{"zh-TW":["解決；決心","解決；決定"],"en":["to find a solution to a problem","to decide firmly","to find a solution; to decide firmly"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"solve","meaning":"loosen (鬆開)"},"logic":"再次鬆開（解開問題），即「解決」。"}', 'resolve a conflict / resolve an issue / resolve to; resolve an issue / resolve a dispute / resolve to do', '[{"en":"We need to resolve this issue quickly.","zh-TW":"我們需要快速解決這個問題。"},{"en":"She resolved to study harder.","zh-TW":"她決心更用功讀書。"},{"en":"We need to resolve this issue immediately.","zh-TW":"我們需要立即解決這問題。"},{"en":"The dispute was resolved through mediation.","zh-TW":"糾紛通過調解解決了。"}]', '{"noun":"resolution","adjective":"resolute"}', NULL, 3, 1747),
(1748, 'resort', '/rɪˈzɔːrt/', 'noun', '{"zh-TW":["度假村","手段"],"en":["a vacation place","a course of action"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sort","meaning":"go out (出去)"}}', 'as a last resort / resort to / tourist resort', '[{"en":"We should use legal action as a last resort.","zh-TW":"我們應將法律行動作為最後手段。"},{"en":"The conference was held at a beach resort.","zh-TW":"會議在海灘度假村舉行。"}]', '{"verb":"resort"}', NULL, 2, 1748),
(1749, 'resource', '/rɪˈsɔːrs/', 'noun', '{"zh-TW":["資源"],"en":["a supply that can be used"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"source","meaning":"rise (升起)"}}', 'human resources / natural resources / allocate resources', '[{"en":"We need to allocate resources more efficiently.","zh-TW":"我們需要更有效地分配資源。"},{"en":"Human resources handles employee matters.","zh-TW":"人力資源部處理員工事務。"}]', '{"adjective":"resourceful","verb":"resource"}', NULL, 3, 1749);
