(1750, 'respond', '/rɪˈspɒnd/', 'verb', '{"zh-TW":["回應；回覆"],"en":["to reply; to react"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"spond","meaning":"promise (承諾)"}}', 'respond to / respond quickly / respond in writing', '[{"en":"Please respond to the email by Friday.","zh-TW":"請於週五前回覆郵件。"},{"en":"The company responded quickly to the crisis.","zh-TW":"公司迅速回應了危機。"}]', '{"noun":"response, respondent","adjective":"responsive"}', NULL, 3, 1750),
(1751, 'rest', '/rɛst/', 'noun', '{"zh-TW":["休息；其餘的"],"en":["a period of relaxing","the remaining part"]}', NULL, 'the rest of / get some rest', '[{"en":"I will handle the rest of the tasks.","zh-TW":"我會處理剩下的任務。"},{"en":"Get some rest before the trip.","zh-TW":"出差前好好休息。"}]', '{"noun":"rest","verb":"rest","adjective":"restful","adjective2":"restless"}', NULL, 1, 1751),
(1752, 'restoration', '/ˌrestəˈreɪʃn/', 'noun', '{"zh-TW":["修復；恢復"],"en":["the act of returning something to its original condition"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"stor","meaning":"set up (建立)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"重新建立的過程，即「修復」。"}', 'art restoration / building restoration', '[{"en":"The restoration of the painting took three years.","zh-TW":"這幅畫的修復花了三年。"},{"en":"The old building underwent a complete restoration.","zh-TW":"這棟老建築進行了全面修復。"}]', '{"verb":"restore"}', NULL, 4, 1752),
(1753, 'restore', '/rɪˈstɔːr/', 'verb', '{"zh-TW":["恢復；修復"],"en":["to bring back to a former condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"store","meaning":"build (建造)"}}', 'restore confidence / restore service / restore to', '[{"en":"We aim to restore customer confidence.","zh-TW":"我們旨在恢復客戶信心。"},{"en":"Service has been fully restored.","zh-TW":"服務已完全恢復。"}]', '{"noun":"restoration"}', NULL, 3, 1753),
(1754, 'restrict', '/rɪˈstrɪkt/', 'verb', '{"zh-TW":["限制；約束"],"en":["to put a limit on"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"strict","meaning":"draw tight (拉緊)"}}', 'restrict access / restrict spending / restricted area', '[{"en":"Access is restricted to authorized personnel.","zh-TW":"僅限授權人員進入。"},{"en":"The budget restricts our spending options.","zh-TW":"預算限制了我們的開支選項。"}]', '{"noun":"restriction","adjective":"restrictive, restricted"}', NULL, 3, 1754),
(1755, 'restructure', '/ˌriːˈstrʌktʃər/', 'verb', '{"zh-TW":["重組；改組"],"en":["to organize differently"]}', NULL, 'restructure debt / corporate restructuring', '[{"en":"The company plans to restructure its divisions.","zh-TW":"公司計畫重組其部門。"},{"en":"Debt restructuring saved the business.","zh-TW":"債務重組拯救了這家企業。"}]', '{"verb":"restructure","noun":"restructuring"}', NULL, 4, 1755),
(1756, 'result', '/rɪˈzʌlt/', 'noun', '{"zh-TW":["結果"],"en":["an outcome; a consequence"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sult","meaning":"jump (跳)"}}', 'as a result / achieve results / result in', '[{"en":"As a result of the merger, profits increased.","zh-TW":"合併的結果是利潤增加了。"},{"en":"The campaign resulted in higher sales.","zh-TW":"活動帶來了更高的銷售額。"}]', '{"verb":"result","adjective":"resulting, resultant"}', NULL, 2, 1756),
(1757, 'resume', '/rɪˈzjuːm/', 'verb', '{"zh-TW":["恢復；繼續"],"en":["to begin again after a pause"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sume","meaning":"take (拿)"}}', 'resume work / resume operations / resume negotiations', '[{"en":"Operations will resume on Monday.","zh-TW":"營運將於週一恢復。"},{"en":"Talks are expected to resume next week.","zh-TW":"會談預計下週恢復。"}]', '{"noun":"resumption"}', NULL, 2, 1757),
(1758, 'retail', '/ˈriːteɪl/', 'noun', '{"zh-TW":["零售"],"en":["the sale of goods to the public in small quantities","the sale of goods to the public"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"tail","meaning":"cut (切割)"},"logic":"再次切割分售，即「零售」。"}', 'retail price / retail store / retail industry', '[{"en":"The retail price is higher than the wholesale price.","zh-TW":"零售價比批發價高。"},{"en":"She has years of experience in retail.","zh-TW":"她有多年零售業經驗。"},{"en":"The retail price is $49.99.","zh-TW":"零售價為49.99美元。"},{"en":"She has 10 years of retail experience.","zh-TW":"她有十年零售經驗。"}]', '{"noun":"retailer","verb":"retail"}', NULL, 2, 1758),
(1759, 'retain', '/rɪˈteɪn/', 'verb', '{"zh-TW":["保留；留住","保持；留住"],"en":["to keep; to continue to have","to continue to have; to keep"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tain","meaning":"hold (持有)"}}', 'retain customers / retain employees / retain the right; retain customers / retain knowledge / retention rate', '[{"en":"The company strives to retain top talent.","zh-TW":"公司努力留住頂尖人才。"},{"en":"We retain the right to modify terms.","zh-TW":"我們保留修改條款的權利。"},{"en":"Customer retention is a key metric.","zh-TW":"客戶留存率是關鍵指標。"},{"en":"How do we retain skilled workers?","zh-TW":"我們如何留住熟練工人？"}]', '{"noun":"retention","adjective":"retentive"}', NULL, 2, 1759),
(1760, 'retire', '/rɪˈtaɪər/', 'verb', '{"zh-TW":["退休"],"en":["to stop working due to age"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tire","meaning":"draw (拉)"}}', 'retire from / retirement age / retire early', '[{"en":"She plans to retire at 60.","zh-TW":"她計劃60歲退休。"},{"en":"He retired from the company after 30 years.","zh-TW":"他在公司工作30年後退休。"}]', '{"noun":"retirement, retiree","adjective":"retired"}', NULL, 2, 1760),
(1761, 'retrieve', '/rɪˈtriːv/', 'verb', '{"zh-TW":["取回；檢索","取回"],"en":["to get back; to find and bring back","to get something back"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"trieve","meaning":"find (找到)"}}', 'retrieve data / retrieve information / retrieve from; retrieve data / retrieve information / information retrieval', '[{"en":"We can retrieve the deleted files.","zh-TW":"我們可以檢索已刪除的文件。"},{"en":"The system retrieves data automatically.","zh-TW":"系統自動檢索數據。"},{"en":"The system can retrieve archived records.","zh-TW":"系統可以檢索存檔記錄。"},{"en":"Click here to retrieve your password.","zh-TW":"點擊此處找回密碼。"}]', '{"noun":"retrieval"}', NULL, 3, 1761),
(1762, 'return', '/rɪˈtɜːrn/', 'verb', '{"zh-TW":["返回；歸還","回報"],"en":["to come or go back","to give back","profit"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"turn","meaning":"turn (轉)"}}', 'return on investment / return a call / return policy', '[{"en":"The return on investment exceeded expectations.","zh-TW":"投資回報超出預期。"},{"en":"Please return the signed contract.","zh-TW":"請歸還已簽署的合約。"}]', '{"noun":"return"}', NULL, 2, 1762),
(1763, 'reveal', '/rɪˈviːl/', 'verb', '{"zh-TW":["揭露；顯示","揭示；透露"],"en":["to make known something previously hidden","to make known; to show"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"veal","meaning":"veil/cover (遮蓋)"},"logic":"把遮蓋拉回，即「揭露」。"}', 'reveal the truth / reveal information / reveal a secret; reveal information / reveal the truth / reveal findings', '[{"en":"The investigation revealed new evidence.","zh-TW":"調查揭露了新證據。"},{"en":"She revealed her plans for the future.","zh-TW":"她透露了未來的計畫。"},{"en":"The audit revealed several discrepancies.","zh-TW":"審計揭示了幾處差異。"},{"en":"The survey revealed customer preferences.","zh-TW":"調查揭示了客戶偏好。"}]', '{"noun":"revelation","adjective":"revealing"}', NULL, 2, 1763),
(1764, 'revenue', '/ˈrevənjuː/', 'noun', '{"zh-TW":["收入；營收","營收"],"en":["income, especially of a company or organization","income from business activities","income earned by a company"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"venue","meaning":"come (來)"},"logic":"回來的錢，即「收入」。"}', 'annual revenue / revenue growth / generate revenue; revenue stream / revenue growth / total revenue', '[{"en":"The company''s annual revenue exceeded $1 billion.","zh-TW":"公司年營收超過10億美元。"},{"en":"Online sales are a major source of revenue.","zh-TW":"線上銷售是主要收入來源。"},{"en":"Annual revenue reached $50 million.","zh-TW":"年營收達到五千萬美元。"},{"en":"The new product line generates significant revenue.","zh-TW":"新產品線產生了可觀收入。"},{"en":"Total revenue exceeded expectations.","zh-TW":"總營收超出預期。"},{"en":"We need to diversify revenue streams.","zh-TW":"我們需要多元化收入來源。"}]', NULL, NULL, 3, 1764),
(1765, 'reverse', '/rɪˈvɜːrs/', 'verb', '{"zh-TW":["逆轉；撤銷"],"en":["to change to the opposite"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"verse","meaning":"turn (轉)"}}', 'reverse a decision / reverse the trend / in reverse', '[{"en":"The board reversed its earlier decision.","zh-TW":"董事會撤銷了先前的決定。"},{"en":"We need to reverse this downward trend.","zh-TW":"我們需要逆轉下降趨勢。"}]', '{"noun":"reversal","adjective":"reversible"}', NULL, 3, 1765),
(1766, 'review', '/rɪˈvjuː/', 'noun', '{"zh-TW":["審查；評論"],"en":["an examination; an assessment"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"view","meaning":"see (看)"}}', 'performance review / under review / review process', '[{"en":"The application is currently under review.","zh-TW":"申請目前正在審查中。"},{"en":"Annual performance reviews start next week.","zh-TW":"年度績效考核下週開始。"}]', '{"verb":"review","noun":"reviewer"}', NULL, 2, 1766),
(1767, 'revise', '/rɪˈvaɪz/', 'verb', '{"zh-TW":["修改；修訂","修訂"],"en":["to change or correct"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"vise","meaning":"see (看)"}}', 'revise the budget / revise upward / revised edition; revise the plan / revised estimate / subject to revision', '[{"en":"We need to revise the budget estimates.","zh-TW":"我們需要修改預算估計。"},{"en":"The forecast has been revised upward.","zh-TW":"預測已被上調修正。"},{"en":"The policy was revised last quarter.","zh-TW":"政策在上季度進行了修訂。"},{"en":"All figures are subject to revision.","zh-TW":"所有數字可能會修訂。"}]', '{"noun":"revision"}', NULL, 2, 1767),
(1768, 'revolve', '/rɪˈvɒlv/', 'verb', '{"zh-TW":["圍繞；旋轉"],"en":["to move in a circle; to center on"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"volve","meaning":"roll (滾動)"}}', 'revolve around / revolving door / revolving credit', '[{"en":"The discussion revolved around cost reduction.","zh-TW":"討論圍繞著降低成本進行。"},{"en":"Our strategy revolves around innovation.","zh-TW":"我們的策略以創新為中心。"}]', '{"adjective":"revolving","noun":"revolution"}', NULL, 3, 1768),
(1769, 'reward', '/rɪˈwɔːrd/', 'noun', '{"zh-TW":["獎勵；報酬","獎勵"],"en":["something given in recognition","to give something good in return for effort"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"ward","meaning":"watch (看)"}}', 'reward for / rewards program / risk and reward; reward employees / reward loyalty / financially rewarding', '[{"en":"Hard work will bring its own reward.","zh-TW":"努力工作自有回報。"},{"en":"The company has a generous rewards program.","zh-TW":"公司有優厚的獎勵計劃。"},{"en":"We reward employees for excellent performance.","zh-TW":"我們獎勵表現優秀的員工。"},{"en":"The career is both challenging and rewarding.","zh-TW":"這份職業既有挑戰性又有回報。"}]', '{"verb":"reward","adjective":"rewarding","noun":"reward"}', NULL, 2, 1769),
(1770, 'rich', '/rɪtʃ/', 'adjective', '{"zh-TW":["富有的；豐富的"],"en":["having a lot of money","containing a lot of something"]}', NULL, 'rich in / get rich', '[{"en":"The region is rich in natural resources.","zh-TW":"這個地區自然資源豐富。"},{"en":"The data provides rich insights.","zh-TW":"數據提供了豐富的洞見。"}]', '{"adjective":"rich","noun":"riches","adverb":"richly","verb":"enrich"}', NULL, 1, 1770),
(1771, 'ride', '/raɪd/', 'verb', '{"zh-TW":["騎；乘坐"],"en":["to sit on and control","to travel in a vehicle"]}', NULL, 'ride sharing / free ride', '[{"en":"Ride-sharing apps reduced transport costs.","zh-TW":"共乘應用程式降低了交通成本。"},{"en":"There is no free ride in business.","zh-TW":"商場上沒有不勞而獲。"}]', '{"verb":"ride","noun":"ride","noun2":"rider"}', NULL, 1, 1771),
(1772, 'rigid', '/ˈrɪdʒɪd/', 'adjective', '{"zh-TW":["嚴格的；僵硬的"],"en":["strict; not flexible"]}', '{"root":{"text":"rig","meaning":"stiff (僵硬)"}}', 'rigid rules / rigid structure / rigid schedule', '[{"en":"The company has very rigid policies.","zh-TW":"公司有非常嚴格的政策。"},{"en":"A rigid schedule leaves no room for creativity.","zh-TW":"僵化的日程不留創造空間。"}]', '{"noun":"rigidity","adverb":"rigidly"}', NULL, 2, 1772),
(1773, 'ring', '/rɪŋ/', 'verb', '{"zh-TW":["響鈴；打電話"],"en":["to make a sound like a bell","to telephone"]}', NULL, 'ring a bell / give someone a ring', '[{"en":"Does the name ring a bell?","zh-TW":"這個名字你聽起來熟悉嗎？"},{"en":"Give me a ring tomorrow morning.","zh-TW":"明天早上打電話給我。"}]', '{"verb":"ring","noun":"ring"}', NULL, 1, 1773),
(1774, 'rise', '/raɪz/', 'verb', '{"zh-TW":["上升；增加"],"en":["to move upward","to increase"]}', NULL, 'give rise to / on the rise', '[{"en":"Remote work is on the rise.","zh-TW":"遠端工作正在增加。"},{"en":"This gave rise to new regulations.","zh-TW":"這引發了新的法規。"}]', '{"verb":"rise","noun":"rise"}', NULL, 1, 1774),
(1775, 'risk', '/rɪsk/', 'noun', '{"zh-TW":["風險","冒...的風險"],"en":["the possibility of danger or loss","to expose to danger"]}', NULL, 'take a risk / risk management / at risk / risk assessment; risk losing / risk assessment / risk management / at risk', '[{"en":"Every investment involves some degree of risk.","zh-TW":"每項投資都涉及一定程度的風險。"},{"en":"We need a comprehensive risk assessment.","zh-TW":"我們需要全面的風險評估。"},{"en":"We risk losing market share if we don''t innovate.","zh-TW":"如不創新我們就有失去市佔率的風險。"},{"en":"Effective risk management is crucial.","zh-TW":"有效的風險管理至關重要。"}]', '{"verb":"risk","adjective":"risky","noun":"risk"}', NULL, 1, 1775),
