(1780, 'rotate', '/roʊˈteɪt/', 'verb', '{"zh-TW":["輪換；旋轉"],"en":["to move in a circle; to take turns"]}', '{"root":{"text":"rot","meaning":"wheel (輪)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'rotate duties / job rotation / rotating schedule', '[{"en":"Staff rotate between departments quarterly.","zh-TW":"員工每季度在部門間輪換。"},{"en":"The chairperson role rotates annually.","zh-TW":"主席一職每年輪換。"}]', '{"noun":"rotation","adjective":"rotating, rotational"}', NULL, 2, 1780),
