(1782, 'round', '/raʊnd/', 'noun', '{"zh-TW":["一輪；回合"],"en":["a series or cycle","approximately"]}', NULL, 'round of funding / year-round', '[{"en":"The startup raised a second round of funding.","zh-TW":"新創公司完成了第二輪融資。"},{"en":"The resort is open year-round.","zh-TW":"度假村全年開放。"}]', '{"noun":"round","adjective":"round","verb":"round","adverb":"around"}', NULL, 2, 1782),
