(1784, 'routine', '/ruːˈtiːn/', 'noun', '{"zh-TW":["例行公事；日常工作","例行的；常規的"],"en":["a regular way of doing things","regular; done as part of normal procedure"]}', NULL, 'daily routine / routine maintenance / routine procedure; routine check / routine inspection / routine maintenance', '[{"en":"Routine maintenance is scheduled for Sunday.","zh-TW":"例行維護安排在週日。"},{"en":"It became part of the daily routine.","zh-TW":"它成為了日常工作的一部分。"},{"en":"This is just a routine inspection.","zh-TW":"這只是例行檢查。"},{"en":"Routine maintenance keeps equipment running.","zh-TW":"例行維護使設備正常運行。"}]', '{"adjective":"routine","adverb":"routinely","noun":"routine"}', NULL, 3, 1784),
