(1788, 'sad', '/sæd/', 'adjective', '{"zh-TW":["悲傷的；令人遺憾的"],"en":["feeling unhappy","unfortunate"]}', NULL, 'sad news / sadly', '[{"en":"I have sad news about the layoffs.","zh-TW":"我有關於裁員的壞消息。"},{"en":"Sadly, the branch will close.","zh-TW":"不幸的是，分公司將關閉。"}]', '{"adjective":"sad","noun":"sadness","adverb":"sadly","verb":"sadden"}', NULL, 1, 1788),
(1789, 'safe', '/seɪf/', 'adjective', '{"zh-TW":["安全的"],"en":["protected from danger"]}', NULL, 'safe and sound / play it safe', '[{"en":"All employees arrived safe and sound.","zh-TW":"所有員工都安全抵達。"},{"en":"Let''s play it safe with this investment.","zh-TW":"這項投資我們保守一點。"}]', '{"adjective":"safe","noun":"safety","adverb":"safely","verb":"safeguard"}', NULL, 1, 1789),
(1790, 'safeguard', '/ˈseɪfɡɑːrd/', 'noun, verb', '{"zh-TW":["保障措施；防護","保護；防衛"],"en":["a measure taken to protect","to protect from harm"]}', NULL, 'safeguard against / safeguard interests', '[{"en":"We need safeguards against data breaches.","zh-TW":"我們需要防範資料洩露的保障措施。"},{"en":"The policy safeguards employees'' rights.","zh-TW":"該政策保障了員工的權利。"}]', '{"noun":"safeguard","verb":"safeguard"}', NULL, 3, 1790),
