(1792, 'sale', '/seɪl/', 'noun', '{"zh-TW":["銷售；特賣"],"en":["the act of selling","a period when goods are sold at reduced prices"]}', '{"root":{"text":"sale","meaning":"sell (賣)"},"logic":"販售的行為或特賣活動。"}', 'on sale / sales figures / for sale', '[{"en":"The house is for sale.","zh-TW":"這棟房子出售中。"},{"en":"Winter coats are on sale this week.","zh-TW":"冬季外套本週特價。"}]', '{"noun":"salesperson","verb":"sell"}', NULL, 1, 1792),
