(1794, 'sanction', '/ˈsæŋkʃən/', 'noun', '{"zh-TW":["制裁；許可","制裁；處罰","批准；認可"],"en":["a penalty imposed on a country; official approval","a penalty for breaking a law","to give official permission"]}', NULL, 'economic sanctions / impose sanctions; impose sanctions / economic sanctions / lift sanctions', '[{"en":"The country faces economic sanctions.","zh-TW":"該國面臨經濟制裁。"},{"en":"Sanctions were imposed on the regime.","zh-TW":"對該政權實施了制裁。"},{"en":"The government imposed economic sanctions.","zh-TW":"政府實施了經濟制裁。"},{"en":"The plan was sanctioned by the board.","zh-TW":"該計畫已獲董事會批准。"}]', '{"verb":"sanction","noun":"sanction"}', NULL, 3, 1794),
