(1796, 'satisfy', '/ˈsætɪsfaɪ/', 'verb', '{"zh-TW":["滿足；使滿意","符合（要求）"],"en":["to fulfill the needs or desires of","to meet requirements"]}', '{"suffix":{"text":"-fy","meaning":"使..."}}', 'satisfy demands / satisfy customers / satisfy requirements', '[{"en":"The results satisfied all stakeholders.","zh-TW":"結果讓所有利害關係人都滿意。"},{"en":"The candidate satisfies all the requirements.","zh-TW":"這位候選人符合所有要求。"}]', '{"noun":"satisfaction","verb":"satisfy","adjective":"satisfactory, satisfied, satisfying"}', NULL, 3, 1796),
(1797, 'save', '/seɪv/', 'verb', '{"zh-TW":["節省；儲蓄","拯救；保存"],"en":["to keep money for future use","to rescue from danger"]}', NULL, 'save money / save time / save energy', '[{"en":"She saves 20% of her income every month.","zh-TW":"她每個月存下收入的20%。"},{"en":"The new system saves us a lot of time.","zh-TW":"新系統為我們節省了大量時間。"}]', '{"noun":"savings, saver","verb":"save"}', NULL, 1, 1797),
(1798, 'scale', '/skeɪl/', 'noun, verb', '{"zh-TW":["規模；比例","擴大規模；攀登"],"en":["the size or extent of something","to increase in size"]}', NULL, 'on a large scale / economies of scale / scale up', '[{"en":"The company plans to scale up production.","zh-TW":"公司計劃擴大生產規模。"},{"en":"The project was carried out on a large scale.","zh-TW":"該專案是大規模進行的。"}]', '{"noun":"scale","verb":"scale","adjective":"scalable"}', NULL, 2, 1798),
