(1800, 'scarce', '/skers/', 'adjective', '{"zh-TW":["稀少的；缺乏的"],"en":["insufficient for the demand; not enough"]}', NULL, 'scarce resources / increasingly scarce', '[{"en":"Clean water is scarce in many regions.","zh-TW":"乾淨的水在許多地區很稀缺。"},{"en":"Skilled workers are becoming increasingly scarce.","zh-TW":"技術工人越來越稀缺。"}]', '{"noun":"scarcity","adjective":"scarce","adverb":"scarcely"}', NULL, 2, 1800),
(1801, 'scenario', '/sɪˈnærioʊ/', 'noun', '{"zh-TW":["情境；劇本","可能的情況"],"en":["a possible sequence of events","a written outline of a story"]}', NULL, 'worst-case scenario / best-case scenario / likely scenario', '[{"en":"In the worst-case scenario, we lose 10% revenue.","zh-TW":"在最壞的情況下，我們會損失10%的收入。"},{"en":"Let''s consider various scenarios before deciding.","zh-TW":"讓我們在決定前考慮各種情境。"}]', '{"noun":"scenario"}', NULL, 3, 1801),
