(1806, 'science', '/ˈsaɪəns/', 'noun', '{"zh-TW":["科學"],"en":["the study of the natural world through observation"]}', NULL, 'data science / computer science', '[{"en":"Data science drives our decisions.","zh-TW":"數據科學驅動我們的決策。"},{"en":"She has a degree in computer science.","zh-TW":"她有電腦科學學位。"}]', '{"noun":"science","noun2":"scientist","adjective":"scientific","adverb":"scientifically"}', NULL, 3, 1806),
