(1811, 'scrutiny', '/ˈskruːtəni/', 'noun', '{"zh-TW":["仔細檢查；審查"],"en":["careful and thorough examination"]}', NULL, 'under scrutiny / public scrutiny / close scrutiny', '[{"en":"The company''s finances are under close scrutiny.","zh-TW":"公司的財務正在接受仔細審查。"},{"en":"His actions came under public scrutiny.","zh-TW":"他的行為受到了公眾的審視。"}]', '{"noun":"scrutiny","verb":"scrutinize"}', NULL, 3, 1811),
(1812, 'sculpture', '/ˈskʌlptʃər/', 'noun', '{"zh-TW":["雕塑"],"en":["a three-dimensional work of art"]}', '{"root":{"text":"sculpt","meaning":"carve (雕刻)"},"suffix":{"text":"-ure","meaning":"result (結果)"},"logic":"雕刻的結果，即「雕塑」。"}', 'marble sculpture / modern sculpture', '[{"en":"The sculpture was made entirely of recycled metal.","zh-TW":"這座雕塑完全由回收金屬製成。"},{"en":"There is a famous sculpture in the park.","zh-TW":"公園裡有一座著名的雕塑。"}]', '{"verb":"sculpt","noun":"sculptor"}', NULL, 3, 1812),
(1813, 'sea', '/siː/', 'noun', '{"zh-TW":["海"],"en":["a large body of saltwater"]}', NULL, 'by sea / at sea', '[{"en":"Goods are shipped by sea.","zh-TW":"貨物經由海運運送。"},{"en":"I am still at sea about the new policy.","zh-TW":"我對新政策還摸不著頭緒。"}]', '{"noun":"sea","adjective":"seaside","noun2":"seaport"}', NULL, 1, 1813),
