(1815, 'seat', '/siːt/', 'noun', '{"zh-TW":["座位"],"en":["a place to sit"]}', NULL, 'take a seat / window seat', '[{"en":"Please take a seat.","zh-TW":"請坐。"},{"en":"I prefer a window seat on flights.","zh-TW":"搭飛機時我偏好靠窗的座位。"}]', '{"noun":"seat","verb":"seat","noun2":"seating"}', NULL, 1, 1815),
(1816, 'secret', '/ˈsiːkrɪt/', 'noun', '{"zh-TW":["秘密"],"en":["something kept hidden"]}', NULL, 'trade secret / keep a secret', '[{"en":"That recipe is a trade secret.","zh-TW":"那個配方是商業機密。"},{"en":"The key to success is no secret.","zh-TW":"成功的關鍵不是秘密。"}]', '{"noun":"secret","adjective":"secret","noun2":"secrecy","adverb":"secretly"}', NULL, 2, 1816),
(1817, 'sector', '/ˈsektər/', 'noun', '{"zh-TW":["部門；領域","行業"],"en":["a distinct area of activity; an industry"]}', NULL, 'private sector / public sector / financial sector', '[{"en":"The technology sector continues to grow rapidly.","zh-TW":"科技行業持續快速增長。"},{"en":"Both the public and private sectors are investing in AI.","zh-TW":"公私部門都在投資人工智慧。"}]', '{"noun":"sector"}', NULL, 2, 1817),
